def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import datetime, timezone, timedelta

    if not isinstance(nanoseconds, int):
        raise ValueError("nanoseconds must be an integer")

    seconds = nanoseconds // 1_000_000_000
    nanos = nanoseconds % 1_000_000_000

    try:
        if tz is None:
            # Create a naive time object
            dt = datetime.utcfromtimestamp(seconds).replace(microsecond=0) + timedelta(microseconds=nanos // 1_000)
            return dt.time()
        else:
            # Create a timezone-aware datetime object
            if isinstance(tz, str):
                tz = timezone(timedelta(hours=int(tz)))
            elif not isinstance(tz, timezone):
                raise ValueError("tz must be a string representing hours offset or a datetime.timezone object")
            dt = datetime.fromtimestamp(seconds, tz).replace(microsecond=0) + timedelta(microseconds=nanos // 1_000)
            return dt.time()
    except (OSError, OverflowError, ValueError) as e:
        raise ValueError(f"Invalid nanoseconds or timezone: {e}")

