            return result
        return wrapper
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    import time
    import functools

    def decorator(func):
        cache = {}
        cache_ordered_keys = []

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = args if typed else args + tuple(sorted(kwargs.items()))
            current_time = timer()

            # Clean up expired cache entries
            while cache_ordered_keys:
                key_to_check = cache_ordered_keys[0]
                if current_time - cache[key_to_check]['time'] > ttl:
                    del cache[key_to_check]
                    del cache_ordered_keys[0]
                else:
                    break

            if key in cache:
                if current_time - cache[key]['time'] <= ttl:
                    return cache[key]['value']

            # If not in cache or expired, call the function and cache the result
            result = func(*args, **kwargs)
            cache[key] = {'value': result, 'time': current_time}
            cache_ordered_keys.append(key)

            # Enforce maxsize
            if maxsize is not None and len(cache) > maxsize:
                oldest_key = cache_ordered_keys.pop(0)
                del cache[oldest_key]

            return result

        return wrapper

    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize is not None and not isinstance(maxsize, int):
        raise TypeError('Expected maxsize to be an integer or None')
    if maxsize is not None and maxsize < 0:
        raise ValueError('Expected maxsize to be a non-negative integer or None')
    if not isinstance(typed, bool):
        raise TypeError('Expected typed to be a boolean')

    def decorator(func):
        cache = {}
        order = []

        def wrapper(*args, **kwargs):
            key = args if not typed else (args, tuple(sorted(kwargs.items())))
            if key in cache:
                order.remove(key)
                order.append(key)
                return cache[key]
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                oldest_key = order.pop(0)
                del cache[oldest_key]
            cache[key] = result
            order.append(key)
            return result

        def cache_info():
            return (len(cache), maxsize, len(cache) == maxsize, len(order))

        def cache_clear():
            cache.clear()
            order.clear()

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear

        return wrapper

    return decorator

