def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Create a dictionary to track the inheritance hierarchy
        inheritance_map = {cls: cls.__bases__ for cls in classes}

        # Function to check if a class is a subclass of another
        def issubclass_recursive(cls, parent):
            return any(issubclass_recursive(base, parent) or base is parent for base in inheritance_map.get(cls, ()))

        # Create a set to store minimal bases
        minimal_set = set(classes)

        # Iterate over all classes to determine minimal bases
        for cls in list(minimal_set):
            for other in list(minimal_set):
                if cls is not other and issubclass_recursive(cls, other):
                    minimal_set.discard(other)

        # Return the ordered list of minimal bases
        return [cls for cls in classes if cls in minimal_set]

    except Exception as e:
        # Handle any unexpected exceptions
        print(f"An error occurred: {e}")
        return []

