def check_digests_present_and_used(self, manifest_files, digests_used):
    if not isinstance(manifest_files, dict) or not isinstance(digests_used, set):
        raise ValueError("manifest_files must be a dictionary and digests_used must be a set")

    all_manifest_digests = set()
    for file_data in manifest_files.values():
        if not isinstance(file_data, dict) or 'digest' not in file_data:
            raise ValueError("Each manifest entry must be a dictionary containing a 'digest' key")
        all_manifest_digests.add(file_data['digest'])

    missing_digests = all_manifest_digests - digests_used
    unused_digests = digests_used - all_manifest_digests

    return {
        'all_digests_present': not missing_digests,
        'all_digests_used': not unused_digests,
        'missing_digests': list(missing_digests),
        'unused_digests': list(unused_digests)
    }

def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise ValueError("The prior must be an instance of InventoryValidator.")

    if not hasattr(self, 'inventory') or not hasattr(prior, 'inventory'):
        raise AttributeError("Both self and prior must have an 'inventory' attribute.")

    # Assuming inventory is a dictionary where keys are item names and values are quantities
    for item, quantity in self.inventory.items():
        if item not in prior.inventory:
            raise ValueError(f"Item '{item}' is in the current inventory but not in the prior inventory.")
        if prior.inventory[item] > quantity:
            raise ValueError(f"Item '{item}' has a higher quantity in the prior inventory than in the current inventory.")

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")
    if not isinstance(version, str):
        raise ValueError("Version must be a string.")

    path_map = {}

    try:
        for logical_path, details in inventory.items():
            if not isinstance(details, dict):
                continue
            if version not in details:
                continue
            files = details.get(version, [])
            if not isinstance(files, list):
                files = [files]
            path_map[logical_path] = set(files)
    except Exception as e:
        raise RuntimeError(f"An error occurred while processing the inventory: {e}")

    return path_map

def validate_fixity(self, fixity, manifest_files):
    if not isinstance(fixity, dict):
        raise ValueError("Fixity should be a dictionary")
    if not isinstance(manifest_files, (list, set)):
        raise ValueError("Manifest files should be a list or a set")

    manifest_files_set = set(manifest_files)

    if 'files' not in fixity:
        raise KeyError("Fixity dictionary does not contain 'files' key")
    if not isinstance(fixity['files'], (list, set)):
        raise ValueError("Fixity files should be a list or a set")

    for file_entry in fixity['files']:
        if not isinstance(file_entry, dict):
            raise ValueError("Each file entry in fixity should be a dictionary")
        if 'path' not in file_entry:
            raise KeyError("File entry does not contain 'path' key")

        file_path = file_entry['path']
        if file_path not in manifest_files_set:
            raise ValueError(f"File {file_path} in fixity is not listed in the manifest")

def _explore_folder(folder):
    import os
    from collections import defaultdict
    import xml.etree.ElementTree as ET

    if not os.path.isdir(folder):
        raise ValueError(f"The provided path {folder} is not a valid directory.")

    package_data = defaultdict(list)

    try:
        for filename in os.listdir(folder):
            if filename.endswith('.xml'):
                file_path = os.path.join(folder, filename)
                tree = ET.parse(file_path)
                root = tree.getroot()
                basename = os.path.splitext(filename)[0]
                package_data[basename].append({'file': filename, 'root': root})
    except ET.ParseError as e:
        raise ValueError(f"Error parsing XML file in {folder}: {e}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

    return dict(package_data)

def add_rendition(self, lang, file_path):
