    self.assets[basename] = file_path

def _explore_zipfile(zip_path):
    import zipfile
    import os
    from xml.etree import ElementTree as ET

    if not isinstance(zip_path, str):
        raise ValueError("zip_path must be a string")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"No file found at the specified path: {zip_path}")

    if not zip_path.endswith('.zip'):
        raise ValueError("The provided path does not point to a zip file")

    package_data = {}

    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            for file_info in z.infolist():
                if file_info.filename.endswith('.xml'):
                    with z.open(file_info) as xml_file:
                        tree = ET.ElementTree(file=xml_file)
                        root = tree.getroot()
                        basename = os.path.splitext(os.path.basename(file_info.filename))[0]
                        if basename not in package_data:
                            package_data[basename] = []
                        package_data[basename].append(ET.tostring(root, encoding='unicode'))
    except zipfile.BadZipFile:
        raise ValueError("The provided file is not a valid zip file")
    except ET.ParseError:
        raise ValueError("One or more files in the zip are not valid XML")

    return package_data

