def pretty(self, indent=0, debug=False):
    try:
        indent_str = '  ' * indent
        result = f"{indent_str}<{self.__class__.__name__}>\n"
        for attr, value in self.__dict__.items():
            if isinstance(value, (list, tuple, set)):
                result += f"{indent_str}  {attr}: [\n"
                for item in value:
                    if hasattr(item, 'pretty'):
                        result += item.pretty(indent + 2, debug) + ",\n"
                    else:
                        result += f"{indent_str}    {item},\n"
                result += f"{indent_str}  ]\n"
            elif isinstance(value, dict):
                result += f"{indent_str}  {attr}: {{\n"
                for key, val in value.items():
                    result += f"{indent_str}    {key}: "
                    if hasattr(val, 'pretty'):
                        result += val.pretty(indent + 2, debug) + ",\n"
                    else:
                        result += f"{val},\n"
                result += f"{indent_str}  }}\n"
            elif hasattr(value, 'pretty'):
                result += f"{indent_str}  {attr}: {value.pretty(indent + 2, debug)}\n"
            else:
                result += f"{indent_str}  {attr}: {value}\n"
        if debug:
            result += f"{indent_str}  id: {id(self)}\n"
        result += f"{indent_str}</{self.__class__.__name__}>\n"
        return result
    except Exception as e:
        return f"{indent_str}<ERROR: {str(e)}>\n"

def absorb(self, args):
    def apply_absorption(expr1, expr2):
        if expr1 == expr2:
            return expr1
        if expr1 == f"~{expr2}" or expr2 == f"~{expr1}":
            return "0" if expr1[0] == "~" else "1"
        if expr1 in expr2 or expr2 in expr1:
            return expr1 if "|" in expr2 else expr2
        return None

    result = []
    i = 0
    while i < len(args):
        expr1 = args[i]
        if i + 1 < len(args):
            expr2 = args[i + 1]
            abs_expr = apply_absorption(expr1, expr2)
            if abs_expr:
                result.append(abs_expr)
                i += 2  # Skip the next expression as it's absorbed
            else:
                result.append(expr1)
                i += 1
        else:
            result.append(expr1)
            i += 1

    # Handle absorption and negative absorption across the entire list
    final_result = []
    i = 0
    while i < len(result):
        expr1 = result[i]
        if i + 1 < len(result):
            expr2 = result[i + 1]
            if f"{expr1} | ({expr1} & {expr2})" in expr2 or f"({expr1} | {expr2}) & {expr1}" in expr2:
                final_result.append(expr1)
                i += 2
            elif f"{expr1} & (~{expr1} | {expr2})" in expr2 or f"({expr1} & {expr2}) | ~{expr1}" in expr2:
                final_result.append(f"{expr1} & {expr2}")
                i += 2
            elif f"{expr1} | (~{expr1} & {expr2})" in expr2 or f"({expr1} | {expr2}) & ~{expr1}" in expr2:
                final_result.append(f"{expr1} | {expr2}")
                i += 2
            else:
                final_result.append(expr1)
                i += 1
        else:
            final_result.append(expr1)
            i += 1

    return final_result

