def _fromutc(self, dt):
    if dt is None or not isinstance(dt, datetime.datetime) or dt.tzinfo is None:
        raise ValueError("dt must be a timezone-aware datetime object")

    try:
        # Convert the given UTC time to the current timezone
        new_dt = dt.astimezone(self)
    except Exception as e:
        raise RuntimeError(f"Error converting datetime to timezone: {e}")

    # Check if the datetime is ambiguous
    if self.localize(new_dt.replace(tzinfo=None)).dst() != self.utcoffset(new_dt):
        # If the UTC offset does not match, it is the first occurrence of the ambiguous time
        return new_dt
    else:
        # Otherwise, it is the second occurrence of the ambiguous time
        return new_dt + self.utcoffset(new_dt) - self.utcoffset(new_dt - timedelta(hours=1))

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        tznames = namefunc()
        return [tz.encode('utf-8') if isinstance(tz, unicode) else tz for tz in tznames]
    except Exception as e:
        raise ValueError("An error occurred while processing the timezone names: {}".format(e))

