        setattr(func, 'vcs_handler', True)
        setattr(func, 'vcs', vcs)
        return func
    return decorator(method) if callable(method) else decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    try:
        # Simulate traversing the storage root hierarchy
        for obj in self.storage_root.iterate_objects():
            num_objects += 1
            is_valid = True

            if validate_objects:
                if not obj.is_valid():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj.id} is not valid.")

            if check_digests:
                if not obj.check_digest():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Digest mismatch for object {obj.id}.")

            if is_valid:
                good_objects += 1

    except Exception as e:
        print(f"An error occurred during hierarchy validation: {e}")

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    if not isinstance(version_dirs, list):
        raise ValueError("version_dirs must be a list of version directory names.")

    if not all(isinstance(d, str) for d in version_dirs):
        raise ValueError("All elements in version_dirs must be strings representing directory names.")

    if not version_dirs:
        return []  # No version directories to validate

    root_inventory = self.load_inventory(version_dirs[0])  # Assuming a method load_inventory exists
    differing_digests = {}

    for version_dir in version_dirs:
        try:
            version_inventory = self.load_inventory(version_dir)
        except Exception as e:
            print(f"Failed to load inventory for {version_dir}: {e}")
            continue

        for item, digest in version_inventory.items():
            if item in root_inventory:
                if root_inventory[item] != digest:
                    differing_digests[item] = digest
            else:
                print(f"Item {item} in {version_dir} not found in root inventory.")

    return differing_digests

def find_path_type(path):
    import os

    try:
        if not path or not isinstance(path, str):
            return "Invalid input: path must be a non-empty string"

        if not os.path.exists(path):
            return f"Path does not exist: {path}"

        if os.path.isfile(path):
            return 'file'

        namaste_file = os.path.join(path, '0=ocfl_1.0')
        if os.path.isfile(namaste_file):
            return 'root'

        namaste_file = os.path.join(path, '0=ocfl_object_1.0')
        if os.path.isfile(namaste_file):
            return 'object'

        return "No OCFL Namaste file found"

    except Exception as e:
        return f"An error occurred: {str(e)}"

