        flags = [action.option_strings for action in parser._actions if action.option_strings]
        flattened_flags = [flag for sublist in flags for flag in sublist]
        return ' '.join(flattened_flags)
    except AttributeError:
        raise ValueError("Provided object is not an instance of argparse.ArgumentParser")

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, subparser in subparsers.items():
        namespace, unknown_args = subparser.parse_known_args(remaining_arguments)
        parsed_arguments[subparser_name] = namespace
        # Update remaining arguments only if this subparser parsed some arguments
        if namespace != argparse.Namespace():
            remaining_arguments = unknown_args

    return parsed_arguments, remaining_arguments

def deep_merge_nodes(nodes):
    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            if isinstance(merged[key], ruamel.yaml.nodes.MappingNode) and isinstance(value_node, ruamel.yaml.nodes.MappingNode):
                merged_value = deep_merge_nodes(merged[key].value + value_node.value)
                merged[key] = ruamel.yaml.nodes.MappingNode(tag=merged[key].tag, value=merged_value)
            else:
                merged[key] = value_node
        else:
            merged[key] = value_node

    return [(ruamel.yaml.nodes.ScalarNode(tag=key.tag, value=key), value) for key, value in merged.items()]

def parse_arguments(*arguments):
    import argparse

    parser = argparse.ArgumentParser(description='Process command-line arguments.')

    try:
        # Assuming the first argument is the script name and should be ignored
        args = parser.parse_args(arguments[1:])
