def parse_arguments(*unparsed_arguments):
    import argparse

    parser = argparse.ArgumentParser(description='Process some command-line arguments.')
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Example subparser 1
    parser_a = subparsers.add_parser('subparser_a', help='Subparser A help')
    parser_a.add_argument('--option1', type=int, help='Option 1 help')

    # Example subparser 2
    parser_b = subparsers.add_parser('subparser_b', help='Subparser B help')
    parser_b.add_argument('--option2', type=str, help='Option 2 help')

    # Global options
    parser.add_argument('--global_option', type=str, help='Global option help')

    try:
        parsed_args = parser.parse_args(unparsed_arguments)
    except SystemExit:
        return {}

    result = {}
    if parsed_args.subparser_name:
        result[parsed_args.subparser_name] = parsed_args
    else:
        result['global'] = parsed_args

    return result

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_results = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        try:
            parsed_namespace, leftover = parser.parse_known_args(remaining_arguments)
            parsed_results[subparser_name] = parsed_namespace
            remaining_arguments = leftover
        except Exception as e:
            # If a subparser fails, log the error and continue with the next one
            print(f"Failed to parse arguments for subparser {subparser_name}: {e}")

    return parsed_results, remaining_arguments

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip().upper()
    try:
        if size.endswith('K'):
            return int(size[:-1]) * 1000
        elif size.endswith('M'):
            return int(size[:-1]) * 1000000
        elif size.endswith('G'):
            return int(size[:-1]) * 1000000000
        elif size.endswith('T'):
            return int(size[:-1]) * 1000000000000
        else:
            return int(size)
    except ValueError:
        raise ValueError("Invalid size format. Use a format like '500K', '1M', '1G', '1T' or just a number.")

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    if not isinstance(dicts, (list, tuple)):
        raise ValueError("Input must be a list or tuple of dictionaries.")
    for d in dicts:
        if not isinstance(d, dict):
            raise ValueError("Each element in the iterable must be a dictionary.")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise ValueError("All values in the dictionaries must be numbers.")
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
