def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet list cannot be empty")
    if number < 0:
        raise ValueError("Number cannot be negative")
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters")

    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    digits = []
    while number > 0:
        digits.append(alphabet[number % base])
        number //= base

    result = ''.join(reversed(digits))

    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    try:
        if not isinstance(flow_params, dict):
            raise ValueError("flow_params must be a dictionary")
        if not isinstance(register_number, (int, str)):
            raise ValueError("register_number must be an integer or string")
        if not isinstance(register_value, str):
            raise ValueError("register_value must be a string")

        for key, value in flow_params.items():
            if isinstance(value, dict) and register_value in value:
                value[register_value] = register_number
            elif isinstance(value, list):
                for item in value:
                    if isinstance(item, dict) and register_value in item:
                        item[register_value] = register_number
    except Exception as e:
        print(f"An error occurred: {e}")

