def split(s, platform='this'):
    import re
    if platform == 'this':
        platform = 1 if re.match(r'posix|linux|darwin', re.sub(r'(_|\d.*)', '', str(platform).lower())) else 0
    if platform == 1:
        pattern = r'(?:(?P<quote>"|\'|)(?P<arg>[^"\']*(?:(?P=quote)[^"\']*)*)(?P=quote)|(?P<unquoted>[^\s]+)'
    elif platform == 0:
        pattern = r'(?:(?P<quote>"|)(?P<arg>[^"]*(?:(?P=quote)[^"]*)*)(?P=quote)|(?P<unquoted>[^\s]+)'
    else:
        raise ValueError("Invalid platform specified. Use 'this', 1 for POSIX, or 0 for Windows/CMD.")

    def parse_args(match):
        quoted = match.group('quote')
        arg = match.group('arg') or match.group('unquoted')
        if quoted:
            arg = re.sub(r'(?<!\\)' + re.escape(quoted), '', arg)
        return arg

    try:
        return [parse_args(m) for m in re.finditer(pattern, s)]
    except TypeError:
        raise ValueError("Input string must be of type str.")

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    try:
        parts = frequency.split()
        if len(parts) != 2:
            raise ValueError("Frequency must be in the format 'number unit'")
        number = int(parts[0])
        unit = parts[1].rstrip('s')  # Remove 's' for plural units like 'weeks'
        if unit == 'week':
            return datetime.timedelta(weeks=number)
        elif unit == 'day':
            return datetime.timedelta(days=number)
        elif unit == 'hour':
            return datetime.timedelta(hours=number)
        elif unit == 'minute':
            return datetime.timedelta(minutes=number)
        elif unit == 'second':
            return datetime.timedelta(seconds=number)
        else:
            raise ValueError(f"Unknown unit of time: {unit}")
    except (ValueError, IndexError) as e:
        raise ValueError(f"Cannot parse frequency: {frequency}") from e

def is_local(host):
