def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess
    import os
    import sys
    import importlib

    if not callable(func):
        raise ValueError("func must be a callable function")

    # Construct the command to run the function
    module_name = func.__module__
    function_name = func.__name__
    if module_name == '__main__':
        raise ValueError("func must be in an importable module")

    if extra_env is None:
        extra_env = {}

    # Prepare environment for subprocess
    env = os.environ.copy()
    env.update(extra_env)

    # Serialize the function call
    function_call = f'{module_name}.{function_name}({" ".join(args)})'
    command = [sys.executable, '-c', f'from {module_name} import {function_name}; {function_call}']

    try:
        result = subprocess.run(command, env=env, timeout=timeout, capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.TimeoutExpired:
        raise TimeoutError(f"The subprocess did not complete within the specified timeout of {timeout} seconds.")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"The subprocess failed with return code {e.returncode}\nOutput:\n{e.output}\nError:\n{e.stderr}")
    except Exception as e:
        raise Exception(f"An error occurred while running the subprocess: {e}")

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise ValueError("The pattern must be a string.")

    if strip:
        pattern = pattern.strip()

    try:
        regex = re.compile(pattern)
    except re.error as e:
        raise ValueError(f"Invalid regex pattern: {e}")

    return regex

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("commands must be a list of strings.")
    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        raise ValueError("args must be a list of strings.")
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("cwd must be a string or None.")
    if not isinstance(verbose, bool):
        raise ValueError("verbose must be a boolean.")
    if not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr must be a boolean.")
    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary or None.")

    full_command = commands + args
    try:
        result = subprocess.run(
            full_command,
            cwd=cwd,
            capture_output=verbose or hide_stderr,
            text=True,
            env=env,
            check=True
        )
        if verbose:
            print("Command output:\n", result.stdout)
        return result.stdout
    except subprocess.CalledProcessError as e:
        error_message = f"Command {' '.join(full_command)} failed with return code {e.returncode}"
        if not hide_stderr:
            error_message += f":\n{e.stderr}"
        raise RuntimeError(error_message) from e
    except Exception as e:
        raise RuntimeError(f"An error occurred while running the command: {e}") from e

