def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    # Find all nodes that are not children (i.e., have no incoming prop edges)
    for s, p, o in graph:
        if p == prop:
            roots.add(o)

    for s, p, o in graph:
        if p == prop:
            if s in roots:
                roots.remove(s)

    return roots

