def isoparse(self, dt_str):
    try:
        from datetime import datetime
        from dateutil import parser
        from dateutil.tz import tzutc, tzoffset

        # Check if the input is a string
        if not isinstance(dt_str, str):
            raise ValueError("The input must be a string.")

        # Parse the ISO-8601 string using dateutil.parser
        parsed_datetime = parser.isoparse(dt_str)

        # Handle time zone information
        if parsed_datetime.tzinfo is not None:
            # Convert UTC offset to tzutc if necessary
            if parsed_datetime.utcoffset() == timedelta(0):
                parsed_datetime = parsed_datetime.replace(tzinfo=tzutc())
        else:
            # Default to UTC if no time zone is specified
            parsed_datetime = parsed_datetime.replace(tzinfo=tzutc())

        return parsed_datetime

    except ValueError as ve:
        raise ValueError(f"Invalid ISO-8601 datetime string: {ve}")
    except Exception as e:
        raise RuntimeError(f"An error occurred while parsing the ISO-8601 datetime string: {e}")

def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    from dateutil import parser as _dateutil_parser
    from dateutil.tz import tzoffset
    import datetime

    if not isinstance(timestr, (str, bytes)):
        raise TypeError("Expected string or bytes, but got {}".format(type(timestr).__name__))

    try:
        if isinstance(default, datetime.datetime):
            parsed = _dateutil_parser._parse(timestr, default=default, ignoretz=ignoretz, tzinfos=tzinfos, **kwargs)
        else:
            parsed = _dateutil_parser.parse(timestr, default=default, ignoretz=ignoretz, tzinfos=tzinfos, **kwargs)
        return parsed
    except _dateutil_parser.ParserError as e:
        raise ValueError("Failed to parse time string '{}' with error: {}".format(timestr, str(e))) from e
    except OverflowError:
        raise OverflowError("Parsed date exceeds the largest valid C integer on your system")
    except Exception as e:
        raise ValueError("An unexpected error occurred while parsing the time string: {}".format(str(e))) from e

def fromutc(self, dt):
    if not isinstance(dt, datetime.datetime):
        raise TypeError("Input must be an instance of datetime.datetime")
    if dt.tzinfo is None:
        raise ValueError("Input datetime must be timezone-aware")

    # Ensure the datetime is in UTC
    if dt.utcoffset() != datetime.timedelta(0):
        dt = dt.astimezone(datetime.timezone.utc)

    # Calculate the adjusted time
    local_time = dt.astimezone(self)
    fold = 0

    # Check for fold state
    # If the local time is ambiguous, determine if it's in the first or second occurrence
    if local_time.replace(fold=1).astimezone(datetime.timezone.utc) == dt:
        fold = 1

    return local_time.replace(fold=fold)

