def validate_from_content(cls, spec_content=None):
    if spec_content is None:
        raise IRValidatorException("Spec content is missing")

    try:
        import yaml
        spec_data = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML: {e}")

    required_fields = ['name', 'version', 'description']
    missing_fields = [field for field in required_fields if field not in spec_data]

    if missing_fields:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing_fields)}")

    return spec_data

def validate_from_file(cls, yaml_file=None):
    import yaml
    import os

    if not yaml_file or not isinstance(yaml_file, str):
        raise ValueError("Invalid file path provided")

    if not os.path.isfile(yaml_file):
        raise FileNotFoundError(f"The file {yaml_file} does not exist")

    try:
        with open(yaml_file, 'r', encoding='utf-8') as file:
            data = yaml.safe_load(file)
    except (yaml.YAMLError, IOError) as e:
        raise IRValidatorException(f"Error reading YAML file: {e}")

    required_fields = {'name', 'version', 'description'}
    missing_fields = required_fields - data.keys()

    if missing_fields:
        raise IRValidatorException(f"Mandatory fields missing in YAML: {', '.join(missing_fields)}")

    return data

def _include_groups(self, parser_dict):
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dictionary")

    if 'include' not in parser_dict:
        return parser_dict

    include_dict = parser_dict.pop('include')

    if not isinstance(include_dict, dict):
        raise ValueError("include directive must be a dictionary")

    for key, value in include_dict.items():
        if key not in parser_dict:
            parser_dict[key] = value
        elif isinstance(parser_dict[key], dict) and isinstance(value, dict):
            parser_dict[key].update(value)
        else:
            raise ValueError(f"Conflicting types for key '{key}' in include directive")

    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    try:
        defaults = {}
        spec = getattr(self, 'spec', None)
        if spec is None:
            raise AttributeError("Instance has no spec attribute")

        for arg, details in spec.items():
            if 'default' in details:
                defaults[arg] = details['default']
            elif 'required' in details and details['required']:
                raise ValueError(f"Required argument '{arg}' has no default value")
            else:
                defaults[arg] = None  # or some other appropriate default

        return defaults

    except Exception as e:
        # Handle exceptions and provide a meaningful message
        raise RuntimeError(f"Failed to resolve default values from spec: {str(e)}")

