def get_option_spec(self, command_name, argument_name):
    try:
        if not isinstance(command_name, str) or not isinstance(argument_name, str):
            raise ValueError("command_name and argument_name must be strings")

        if not command_name or not argument_name:
            raise ValueError("command_name and argument_name must not be empty")

        # Assuming self.options is a dictionary where keys are command names
        # and values are dictionaries of argument names to their specifications
        command_spec = self.options.get(command_name)
