def _get_conditionally_required_args(self, command_name, options_spec, args):
    if not isinstance(command_name, str):
        raise ValueError("command_name must be a string")
    if not isinstance(options_spec, list):
        raise ValueError("options_spec must be a list")
    if not isinstance(args, dict):
        raise ValueError("args must be a dictionary")

    required_args = []
    for option in options_spec:
        if 'required_when' in option:
            condition = option['required_when']
            if isinstance(condition, dict):
                key = condition.get('key')
                value = condition.get('value')
                if key and value and args.get(key) == value:
                    required_args.append(option.get('name'))
            else:
                raise ValueError("required_when must be a dictionary with 'key' and 'value'")
    return required_args

def validate_length_args(self, args):
