    for key, value in args.items():
        max_length = getattr(self, f"{key}_max_length", None)
        if max_length is not None:
            if not isinstance(value, (str, list, tuple)):
                raise ValueError(f"The value of {key} must be a string, list, or tuple")
            if len(value) > max_length:
                raise ValueError(f"The length of {key} ({len(value)}) exceeds the maximum length of {max_length}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary.")

    # Assuming self.choices is a dictionary where keys are argument names and values are lists of valid choices
    if not hasattr(self, 'choices') or not isinstance(self.choices, dict):
        raise AttributeError("Class instance must have a 'choices' attribute which is a dictionary.")

    for arg_name, arg_value in args.items():
        if arg_name in self.choices:
            if arg_value not in self.choices[arg_name]:
                raise ValueError(f"Value for '{arg_name}' must be one of {self.choices[arg_name]}. Got '{arg_value}'.")

def validate_min_max_args(self, args):
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary.")

    for arg_name, arg_info in args.items():
        if not isinstance(arg_info, dict):
            raise ValueError(f"Argument information for '{arg_name}' must be a dictionary.")

        value = arg_info.get('value')
        min_val = arg_info.get('min')
        max_val = arg_info.get('max')

        if value is None:
            raise ValueError(f"Value for argument '{arg_name}' is missing.")
        if min_val is None or max_val is None:
            raise ValueError(f"Both 'min' and 'max' values must be provided for argument '{arg_name}'.")

        if not isinstance(value, (int, float)):
            raise ValueError(f"Value for argument '{arg_name}' must be an integer or float.")
        if not isinstance(min_val, (int, float)) or not isinstance(max_val, (int, float)):
            raise ValueError(f"Both 'min' and 'max' values for argument '{arg_name}' must be integers or floats.")

        if value < min_val or value > max_val:
            raise ValueError(f"Value for argument '{arg_name}' is out of the allowed range. Expected: [{min_val}, {max_val}], Got: {value}")

def create_complex_argument_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        if not isinstance(subcommand, str) or not subcommand:
            raise ValueError("subcommand must be a non-empty string")
        if not isinstance(type_name, str) or not type_name:
            raise ValueError("type_name must be a non-empty string")
        if not isinstance(option_name, str) or not option_name:
            raise ValueError("option_name must be a non-empty string")
        if not isinstance(spec_option, dict) or not spec_option:
            raise ValueError("spec_option must be a non-empty dictionary")

        # Assuming the complex type is a dictionary structure for demonstration
        complex_type_instance = {
            'subcommand': subcommand,
            'type_name': type_name,
            'option_name': option_name,
            'specification': spec_option
        }

        return complex_type_instance

    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def get_nested_custom_and_control_args(self, args):
    if not isinstance(args, dict):
        raise ValueError("Input args must be a dictionary")

    control_args = {}
    nested_args = {}

    for key, value in args.items():
        if key.startswith('control_'):
            control_args[key] = value
        elif key.startswith('custom_'):
            continue  # Custom arguments are ignored for nested args
        else:
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if extra_vars is None:
        extra_vars = []
    elif not isinstance(extra_vars, list):
        raise ValueError("extra_vars must be a list or None")

    for item in extra_vars:
        if not isinstance(item, dict):
            raise ValueError("Each item in extra_vars must be a dictionary")
        vars_dict.update(item)

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import os
    from collections import defaultdict

    if not playbook_path or not os.path.isfile(playbook_path):
        raise ValueError("Invalid playbook path provided")

    cmd = ['ansible-playbook', playbook_path]

    if verbose:
        cmd.extend(['-v'] * verbose)

    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise ValueError("extra_vars must be a dictionary")
        extra_vars_str = ' '.join(f"{k}={v}" for k, v in extra_vars.items())
        cmd.extend(['--extra-vars', extra_vars_str])

    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise ValueError("ansible_args must be a dictionary")
        for arg, value in ansible_args.items():
            if value is not None:
                cmd.extend([f"--{arg}", str(value)])
            else:
                cmd.append(f"--{arg}")

    try:
        result = subprocess.run(cmd, check=True, text=True, capture_output=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        return f"An error occurred: {e.stderr}"

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    try:
        # Construct the command with extra-vars
        extra_vars = ' '.join([f"{key}={value}" for key, value in vars_dict.items()])
        command = f"ansible-playbook {' '.join(cli_args)} --extra-vars '{extra_vars}'"

        # Execute the command using Infrared's plugin capabilities
        result = ir_plugin.execute(command, workspace=ir_workspace)

        return result

    except TypeError as e:
        raise TypeError("Invalid argument types provided.") from e
    except Exception as e:
        raise RuntimeError(f"An error occurred while running the playbook: {e}") from e

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    if not isinstance(parser_name, str):
        raise ValueError("parser_name must be a string")
    if not isinstance(values_dict, dict):
        raise ValueError("values_dict must be a dictionary")

    # Example conversion rules, extend as necessary based on parser_name
    conversion_rules = {
        'main': {
            'age': int,
            'flag': bool,
            'price': float
        },
        'virsh': {
            'count': int,
            'enable': bool
        },
        'ospd': {
            'timeout': float,
            'active': bool
        }
    }

    rules = conversion_rules.get(parser_name, {})

    for key, value in values_dict.items():
        if key in rules:
            try:
                values_dict[key] = rules[key](value)
            except (ValueError, TypeError) as e:
                raise ValueError(f"Error converting {key} to {rules[key].__name__}: {e}")

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    try:
        spec_file_path = os.path.join(plugin_dir, 'spec.json')
        if not os.path.isfile(spec_file_path):
            raise FileNotFoundError(f"Spec file not found at: {spec_file_path}")

        with open(spec_file_path, 'r') as file:
            spec_data = json.load(file)

        if not isinstance(spec_data, dict):
            raise ValueError("Spec file does not contain a valid dictionary.")

        return flatten_dict(spec_data)

    except (FileNotFoundError, json.JSONDecodeError, ValueError) as e:
        print(f"Error processing plugin spec: {e}")
        return {}

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    config_path = os.getenv('CONFIG_PATH')
    if not config_path:
        default_config_path = '/path/to/default/config'  # Define a default path or mechanism to determine it
        os.environ['CONFIG_PATH'] = default_config_path
        print(f"CONFIG_PATH environment variable set to {default_config_path}")
    else:
        print(f"CONFIG_PATH environment variable is already set to {config_path}")

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise ValueError("Both path and root must be strings.")

    if not path.startswith(root):
        raise ValueError("Path does not start with the specified root.")

    stripped_path = path[len(root):]
    # Remove any leading slash from the stripped path if the original path had a slash after the root
    if root and path[len(root):len(root)+1] == '/':
        stripped_path = stripped_path[1:]

    return stripped_path
